/**
 * THIRD_PARTY_NOTICES.md: the license texts of everything the browser bundle (public/app.js,
 * public/chunks/) contains, generated by scripts/build.mjs from esbuild's metafile, so the
 * notices cannot drift from what ships. Each bundled package's own license file is copied from
 * node_modules; a package that ships none gets its declared license's standard text with the
 * author from its package.json, and the file says so. The icons' credits stay in
 * public/icons/CREDITS.md; the MIT-licensed icons' license text is added here.
 *
 *   import { renderNotices } from "./third-party-notices.mjs";
 *   const text = renderNotices(result.metafile, root);
 *
 * The output depends only on the metafile and node_modules (no dates), so CI can check that the
 * committed file is fresh.
 */
import { existsSync, readFileSync, readdirSync } from "node:fs";
import path from "node:path";

const LICENSE_FILE = /^(licen[cs]e|copying|notice)([-_.][a-z0-9-]+)?(\.(md|txt|markdown|rst))?$/i;
const CODE_FILE = /\.(c?js|mjs|ts|json)$/i;

const MIT = (holder) => `MIT License

Copyright (c) ${holder}

Permission is hereby granted, free of charge, to any person obtaining a copy
of this software and associated documentation files (the "Software"), to deal
in the Software without restriction, including without limitation the rights
to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
copies of the Software, and to permit persons to whom the Software is
furnished to do so, subject to the following conditions:

The above copyright notice and this permission notice shall be included in all
copies or substantial portions of the Software.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
SOFTWARE.`;

/** Standard texts for declared licenses whose package ships no license file. */
const TEMPLATES = { MIT };

/** node_modules/<name> (or a nested node_modules/.../<name>) folder of a metafile input path. */
function packageDir(input) {
  const parts = input.split("/");
  const i = parts.lastIndexOf("node_modules");
  if (i < 0 || i + 1 >= parts.length) return null;
  const name = parts[i + 1].startsWith("@") ? `${parts[i + 1]}/${parts[i + 2]}` : parts[i + 1];
  return { dir: [...parts.slice(0, i + 1), name].join("/"), name };
}

function declaredLicense(pkg) {
  const raw = typeof pkg.license === "string" ? pkg.license
    : pkg.license?.type ? pkg.license.type
    : Array.isArray(pkg.licenses) ? pkg.licenses.map((l) => l.type ?? l).join(" OR ")
    : null;
  return raw?.replace(/^\((.*)\)$/, "$1") ?? null;
}

function authorOf(pkg) {
  const a = pkg.author;
  if (!a) return null;
  return typeof a === "string" ? a.replace(/\s*[<(].*$/, "").trim() : a.name ?? null;
}

const repoUrl = (pkg) => {
  const r = typeof pkg.repository === "string" ? pkg.repository : pkg.repository?.url;
  const url = (r ?? pkg.homepage ?? "").replace(/^git\+/, "").replace(/\.git$/, "").replace(/^git:\/\//, "https://");
  return /^https?:\/\//.test(url) ? url : /^github:/.test(url) ? `https://github.com/${url.slice(7)}` : "";
};

/** One entry per bundled package (name@version), sorted, with its license texts. */
export function bundledPackages(metafile, root) {
  const seen = new Map();
  for (const input of Object.keys(metafile.inputs)) {
    const p = packageDir(input);
    if (!p || seen.has(p.dir)) continue;
    const pkg = JSON.parse(readFileSync(path.join(root, p.dir, "package.json"), "utf8"));
    const files = readdirSync(path.join(root, p.dir))
      .filter((f) => LICENSE_FILE.test(f) && !CODE_FILE.test(f))
      .sort();
    const texts = files.map((f) => ({ file: f, text: readFileSync(path.join(root, p.dir, f), "utf8").replace(/\r\n/g, "\n").trim() }));
    // A package without a license field: name the license its file starts with.
    const sniffed = texts.length && /^(the )?mit license/i.test(texts[0].text) ? "MIT, from its license file" : "no license field";
    seen.set(p.dir, {
      name: pkg.name ?? p.name,
      version: pkg.version,
      license: declaredLicense(pkg) ?? sniffed,
      url: repoUrl(pkg),
      author: authorOf(pkg),
      texts,
    });
  }
  // The same name@version can be installed twice (nested copies): keep one.
  const unique = new Map();
  for (const entry of seen.values()) unique.set(`${entry.name}@${entry.version}`, entry);
  return [...unique.values()].sort((a, b) => (a.name === b.name ? a.version.localeCompare(b.version, "en", { numeric: true }) : a.name.localeCompare(b.name, "en")));
}

/** The runtime dependencies (installed from npm next to the package, not bundled). */
function runtimeDependencies(root) {
  const pkg = JSON.parse(readFileSync(path.join(root, "package.json"), "utf8"));
  return Object.keys(pkg.dependencies ?? {}).sort().map((name) => {
    const file = path.join(root, "node_modules", name, "package.json");
    const dep = existsSync(file) ? JSON.parse(readFileSync(file, "utf8")) : { version: pkg.dependencies[name] };
    return { name, version: dep.version, license: declaredLicense(dep) ?? "no license field" };
  });
}

/** Authors of the MIT-licensed icons, from public/icons/index.json. */
function mitIconAuthors(root) {
  const file = path.join(root, "public", "icons", "index.json");
  if (!existsSync(file)) return [];
  const counts = new Map();
  for (const icon of JSON.parse(readFileSync(file, "utf8"))) if (icon.license === "mit") counts.set(icon.author, (counts.get(icon.author) ?? 0) + 1);
  return [...counts.entries()].sort((a, b) => a[0].localeCompare(b[0], "en"));
}

export function renderNotices(metafile, root) {
  const packages = bundledPackages(metafile, root);
  const out = [
    "# Third-party notices",
    "",
    "math-board's own code is under the MIT license in [LICENSE](LICENSE). The npm package and the repository also",
    "contain other people's work, which keeps its own license. This file is generated by `npm run build`",
    "(scripts/third-party-notices.mjs) from the build's list of bundled files; do not edit it by hand.",
    "",
    "## Bundled into public/app.js, public/chunks/ and public/assets/",
    "",
    "esbuild bundles browser/app.jsx with these packages (KaTeX's fonts in public/assets/ come with KaTeX):",
    "",
    ...packages.map((p) => `- ${p.name} ${p.version} (${p.license})${p.url ? `: ${p.url}` : ""}`),
    "",
    "## Installed from npm at runtime, not bundled",
    "",
    "npm installs these next to the package, each with its own license file:",
    "",
    ...runtimeDependencies(root).map((d) => `- ${d.name} ${d.version} (${d.license})`),
    "",
    "## Illustrations in public/icons/",
    "",
    "The icon library is built by scripts/build-icons.mjs from Bioicons (https://bioicons.com,",
    "https://github.com/duerrsimon/bioicons). Every icon keeps its own license (CC0, CC-BY 3.0, CC-BY 4.0",
    "or MIT); author, license and source path of each icon are listed in public/icons/CREDITS.md, which is",
    "part of this notice. The icons were normalized for safe display (editor metadata, filters, raster",
    "images and external references removed), which counts as a modification under the CC-BY licenses.",
  ];
  const mit = mitIconAuthors(root);
  if (mit.length) {
    out.push("", "The MIT-licensed icons are by " + mit.map(([a, n]) => `${a} (${n})`).join(", ") + ". For each of them:", "", "```text", MIT("the icon's author, as listed in public/icons/CREDITS.md"), "```");
  }
  out.push("", "## License texts of the bundled packages");
  for (const p of packages) {
    out.push("", `### ${p.name} ${p.version}`, "");
    if (p.texts.length) {
      for (const t of p.texts) out.push(...(p.texts.length > 1 ? [`${t.file}:`, ""] : []), "```text", t.text, "```", "");
    } else if (TEMPLATES[p.license]) {
      out.push(
        `The package ships no license file; its package.json declares ${p.license}${p.author ? ` and names ${p.author} as the author` : ""}. The standard ${p.license} text:`,
        "",
        "```text",
        TEMPLATES[p.license](p.author ?? `the ${p.name} authors`),
        "```",
        "",
      );
    } else {
      throw new Error(`${p.name} ${p.version} ships no license file and declares "${p.license}": add its text to scripts/third-party-notices.mjs`);
    }
    out[out.length - 1] === "" && out.pop();
  }
  return out.join("\n").replace(/```\n\n(?=```)/g, "```\n") + "\n";
}
